#include "stdafx.h"#include "MBR.h"KMBR::KMBR(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Register Used",  "Address",  "Data Type",  "Func. Code",  "Sel. Bit",};BOOL KMBR::OnParsingSingleText( std::string &szText, RECTL *rc ){    for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  if( m_CurParameterID!=-1 )  {    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  return FALSE;}